// Library manifest: every ID the vignette pipeline may reference, grouped by kind (S0-owned).
// status 'available' = implemented in the engine/assets today; 'planned' = reserved for the owner session to build.
// Rules: IDs are lowercase snake_case; versioned assets are referenced as id or id@x.y.z (see docs/vignette-pipeline.md).
// Other sessions do not edit this file: they report additions/status flips to S0.

export const LIBRARY_KINDS = ['sets', 'characters', 'props', 'actions', 'expressions', 'cameraRecipes', 'vfx', 'textStyles', 'sfx', 'music'] as const;
export type LibraryKind = (typeof LIBRARY_KINDS)[number];
export type LibraryStatus = 'available' | 'planned';
export type OwnerSession = 'S0' | 'S1' | 'S2' | 'S3' | 'S4' | 'S5' | 'S6' | 'S7';

export interface LibraryEntry {
  id: string;
  status: LibraryStatus;
  owner: OwnerSession;
  description: string;
  /** script words that map to this entry (director lookup) */
  tags: string[];
  /** versioned assets: published versions (id@x.y.z) */
  versions?: string[];
  /** what the entry is backed by today (asset ref or engine enum), if available */
  source?: string;
}
export interface SetEntry extends LibraryEntry {
  /** placement marks (beat-sheet cast/prop placement); empty = not yet authored */
  marks: string[];
  /** doors for enter:<door> / exit:<door> placements and door events */
  doors: string[];
  /** lighting preset IDs */
  lighting: string[];
}
export interface Library {
  sets: SetEntry[];
  characters: LibraryEntry[];
  props: LibraryEntry[];
  actions: LibraryEntry[];
  expressions: LibraryEntry[];
  cameraRecipes: LibraryEntry[];
  vfx: LibraryEntry[];
  textStyles: LibraryEntry[];
  sfx: LibraryEntry[];
  music: LibraryEntry[];
}

/** lowercase snake_case */
export const ID_PATTERN = /^[a-z][a-z0-9]*(_[a-z0-9]+)*$/;
/** id or id@x.y.z */
export const REF_PATTERN = /^[a-z][a-z0-9]*(_[a-z0-9]+)*(@\d+\.\d+\.\d+)?$/;

type Row = [id: string, description: string, tags: string[], extra?: Partial<LibraryEntry>];
const rows = (owner: OwnerSession, status: LibraryStatus, list: Row[]): LibraryEntry[] =>
  list.map(([id, description, tags, extra]) => ({ id, status, owner, description, tags, ...extra }));
const setRows = (status: LibraryStatus, list: Array<[string, string, string[], Partial<SetEntry>?]>): SetEntry[] =>
  list.map(([id, description, tags, extra]) => ({ id, status, owner: 'S2', description, tags, marks: [], doors: [], lighting: [], ...extra }));

