/** Look up an entry by kind and id or id@x.y.z (the version must be published). */
export function lookup(kind: LibraryKind, ref: string, lib: Library = LIBRARY): LibraryEntry | SetEntry | undefined {
  const [id, version] = ref.split('@');
  const e = (lib[kind] as LibraryEntry[]).find((x) => x.id === id);
  if (!e) return undefined;
  if (version !== undefined && !(e.versions ?? []).includes(version)) return undefined;
  return e;
}
export function idsOf(kind: LibraryKind, status?: LibraryStatus, lib: Library = LIBRARY): string[] {
  return (lib[kind] as LibraryEntry[]).filter((e) => !status || e.status === status).map((e) => e.id);
}

/** Manifest self-check: ID format, uniqueness per kind, non-empty description/tags. */
export function checkLibrary(lib: Library = LIBRARY): string[] {
  const out: string[] = [];
  for (const kind of LIBRARY_KINDS) {
    const seen = new Set<string>();
    for (const e of lib[kind] as LibraryEntry[]) {
      if (!ID_PATTERN.test(e.id)) out.push(`${kind}.${e.id}: not lowercase snake_case`);
      if (seen.has(e.id)) out.push(`${kind}.${e.id}: duplicate`);
      seen.add(e.id);
      if (!e.description) out.push(`${kind}.${e.id}: missing description`);
      if (!e.tags.length) out.push(`${kind}.${e.id}: missing tags`);
      for (const ver of e.versions ?? []) if (!/^\d+\.\d+\.\d+$/.test(ver)) out.push(`${kind}.${e.id}: bad version ${ver}`);
    }
  }
  return out;
}
